export type TagQuery = { path: string, offset?: number, limit?: number, };

export type TagValue = { "type": "string", value: string, } | { "type": "number", value: number, } | { "type": "numbers", value: Array<number>, truncated?: boolean, total?: number, } | { "type": "binary", length: number, } | { "type": "sequence", items: Array<Array<TagNode>>, truncated?: boolean, total?: number, } | { "type": "error", message: string, };

export type TextJustification = "left" | "center" | "right";

export type TextObjectSummary = { 
/**
 * The Graphic Annotation Sequence item it belongs to, zero-based.
 */
item: number, layer: string, 
/**
 * Lines are separated by `\n`.
 */
text: string, 
/**
 * `[left, top, right, bottom]` of the bounding box.
 */
bounding_box: [number, number, number, number] | null, 
/**
 * `left`, `center`, or `right` within the bounding box.
 */
justification: TextJustification | null, anchor: [number, number] | null, 
/**
 * Whether a line joins the text to its anchor point.
 */
anchor_visible: boolean, };

/**
 * Thumbnail query.
 */
export type ThumbnailQuery = { 
/**
 * Longest edge wanted, in device pixels: 1 to the largest of
 * [`THUMBNAIL_SIZE_BUCKETS`], snapped up to the next bucket; absent
 * means [`THUMBNAIL_DEFAULT_SIZE`]. Anything else is `400
 * invalid_query`.
 */
size?: number, 
/**
 * `default` (when absent) for the frame's default presentation, or
 * `full_dynamic`. A thumbnail takes no explicit window.
 */
window_mode?: WindowMode, };

/**
 * The step that produced a thumbnail, reported in
 * [`THUMBNAIL_HEADER_SOURCE`]. `ThumbnailCache` and `FullDecode` are sent
 * today; the others are reserved for the cheaper sources that follow.
 */
export type ThumbnailSource = "thumbnail_cache" | "display_cache" | "raw_cache" | "reduced_decode" | "full_decode";

/**
 * `value = values[clamp(stored - first_value_mapped, 0, values.length - 1)]`.
 */
export type ValueLookupTable = { first_value_mapped: number, values: Array<number>, };

export type ViewerIdentity = { name: string, version: string, build_target: string, build_profile: string, };

/**
 * A VOI LUT: `values[clamp(trunc(modality) - first_value_mapped, 0,
 * values.length - 1)]`, an output of `bits_per_entry` (8 or 16) bits that
 * scales to 8 bits as `(output * 255 + max / 2) / max` in integers, where
 * `max = 2^bits_per_entry - 1`.
 */
export type VoiLookupTable = { first_value_mapped: number, bits_per_entry: number, values: Array<number>, };

export type WindowMode = "default" | "full_dynamic";

export type WindowPreset = { center: number, width: number, };

